function invalidPin() {
    let timerInterval
    Swal.fire({
        title: 'Invalid Pin',
        html: 'Please Enter a valid pin',
        timer: 2000,
        timerProgressBar: true,

        willClose: () => {
            clearInterval(timerInterval)
        }
    })
}
